import CoreGraphics
import Foundation
import Testing
@testable import Layer

/// Runs the labelled sketch fixtures (`LayerTests/Fixtures`, generated by
/// `Tools/SketchBenchmarkHarness`) through the rules and reports accuracy, the confusion
/// matrix, candidate-set recall and escalation rate. Apple Intelligence can't be reached
/// from the Simulator (see the `layer-apple-intelligence-findings` memory note), so the
/// model-dependent parts of the benchmark — System 2 accuracy and its latency — are
/// measured by `Tools/SketchBenchmarkHarness` on macOS instead; this suite is the rules-only
/// half of the same benchmark, run on-device so a regression in the rules themselves shows
/// up here too.
///
/// This is deliberately not a benchmark that fails the build on every accuracy move: the
/// fixtures and the rules will both grow over the staged rollout in
/// `reports/Fast and slow sketch recognition.md`, and a hard-coded percentage would either
/// block legitimate improvements or quietly stop meaning anything. It does assert the
/// invariants that should never slip: every clean fixture reads correctly, and the engine
/// never crashes or returns a reading that isn't even one of the sketch's candidates when
/// escalation didn't happen.
@Suite("Sketch benchmark (rules)")
struct SketchBenchmarkTests {
    private static let fixtures: [SketchFixture] = {
        let bundle = Bundle(for: BundleMarker.self)
        guard let resourceURL = bundle.resourceURL,
              let loaded = try? SketchFixtureCorpus.load(from: resourceURL)
        else { return [] }
        return loaded
    }()

    @Test func theFixtureCorpusLoaded() {
        #expect(Self.fixtures.count > 100, "expected the generated corpus (156 fixtures as of Step B); got \(Self.fixtures.count)")
    }

    @Test func everyCleanFixtureReadsCorrectly() {
        let clean = Self.fixtures.filter { $0.variant == .clean }
        let cases = SketchBenchmarkRunner.runRulesOnly(clean)
        let wrong = cases.filter { $0.observed && $0.finalReading != $0.expected }
        #expect(wrong.isEmpty, "clean fixtures the rules misread: \(wrong.map { "\($0.fixture.id) -> \($0.finalReading)" })")
    }

    @Test func aFinalReadingThatWasntEscalatedIsAlwaysOneOfTheCandidates() {
        let cases = SketchBenchmarkRunner.runRulesOnly(Self.fixtures)
        let impossible = cases.filter { $0.observed && !$0.candidates.isEmpty && !$0.candidates.contains($0.finalReading) }
        #expect(impossible.isEmpty, "the rules gave a reading outside the sketch's own candidates: \(impossible.map(\.fixture.id))")
    }

    @Test func printsTheFullBenchmarkReport() {
        let cases = SketchBenchmarkRunner.runRulesOnly(Self.fixtures)
        let report = SketchBenchmarkMetrics.report(for: cases)
        print("=== Sketch benchmark: rules only (Simulator) ===")
        print("Total cases: \(report.totalCases)")
        print("Overall accuracy: \(String(format: "%.1f", report.overallAccuracy * 100))%")
        print("Candidate-set recall: \(String(format: "%.1f", report.candidateRecall * 100))%")
        print("Escalation rate: \(String(format: "%.1f", report.escalationRate * 100))%")
        for kind in report.perKind {
            print("  \(kind.label): \(kind.correct)/\(kind.total) (\(String(format: "%.1f", kind.accuracy * 100))%)")
        }
        for (pair, accuracy) in report.pairAccuracy.sorted(by: { $0.key < $1.key }) {
            print("  pair \(pair): \(String(format: "%.1f", accuracy * 100))%")
        }
        for confusion in report.confusions {
            print("  confusion \(confusion.expected) -> \(confusion.got): \(confusion.count)")
        }
        // A floor loose enough not to block legitimate changes, strict enough to catch a
        // real regression (an empty or near-empty corpus would also trip this).
        #expect(report.overallAccuracy > 0.6)
    }
}

/// Just something in the `Layer` module/test bundle to resolve from, to find this test
/// bundle's `Bundle`.
private final class BundleMarker {}
